"""Render GitHub-facing release history from the packaged Factorio changelog."""
import argparse
from datetime import date
import json
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[1]
SOURCE = Path("mod/production-flow/changelog.txt")
SEPARATOR = "-" * 99
PREAMBLE = """# Changelog

<!-- Generated by tools/changelog.py. Do not edit this file directly. -->

Release history is maintained in the [Factorio changelog](mod/production-flow/changelog.txt).
Run `python tools/changelog.py --write` after editing it.
See [validation and engineering notes](docs/validation.md) for historical test details.
"""


def parse(text):
    """Keep source ordering, categories and complete wrapped bullet text."""
    releases = []
    seen = set()
    for block in text.split(SEPARATOR):
        lines = [line.rstrip() for line in block.splitlines() if line.strip()]
        if not lines:
            continue
        header = re.fullmatch(r"Version: (\d+\.\d+\.\d+)", lines[0])
        if not header:
            raise ValueError("Expected a Factorio Version: header")
        version = header[1]
        if version in seen:
            raise ValueError(f"Duplicate changelog version: {version}")
        seen.add(version)
        if releases and tuple(map(int, version.split("."))) >= tuple(map(int, releases[-1]["version"].split("."))):
            raise ValueError("Changelog versions must be newest first")
        release = {"version": version, "date": None, "sections": []}
        section = None
        for line in lines[1:]:
            if line.startswith("Date: ") and not release["sections"] and release["date"] is None:
                value = line.removeprefix("Date: ")
                if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                    raise ValueError(f"Invalid changelog date: {value}")
                date.fromisoformat(value)
                release["date"] = value
            elif match := re.fullmatch(r"  ([^:]+):", line):
                section = {"title": match[1], "entries": []}
                release["sections"].append(section)
            elif line.startswith("    - ") and section is not None:
                if not line[6:].strip():
                    raise ValueError(f"Empty changelog bullet in {version}")
                section["entries"].append(line[6:])
            elif line.startswith("      ") and section is not None and section["entries"]:
                section["entries"][-1] += " " + line.strip()
            else:
                raise ValueError(f"Invalid changelog line in {version}: {line}")
        if not release["sections"] or any(not s["entries"] for s in release["sections"]):
            raise ValueError(f"Missing changelog entries in {version}")
        releases.append(release)
    if not releases:
        raise ValueError("Changelog contains no releases")
    return releases


def render_release(release):
    heading = "## " + release["version"]
    if release["date"]:
        heading += " — " + release["date"]
    lines = [heading, ""]
    for section in release["sections"]:
        lines.extend(["### " + section["title"], ""])
        lines.extend("- " + entry for entry in section["entries"])
        lines.append("")
    return "\n".join(lines)


def render(releases):
    return PREAMBLE + "\n" + "\n".join(render_release(r) for r in releases)


def load(root=ROOT):
    releases = parse((root / SOURCE).read_text(encoding="utf-8-sig"))
    version = json.loads((root / "mod/production-flow/info.json").read_text(encoding="utf-8-sig"))["version"]
    if releases[0]["version"] != version:
        raise ValueError(f"Latest changelog version {releases[0]['version']} differs from info.json {version}")
    return releases


def check(root=ROOT):
    expected = render(load(root))
    target = root / "CHANGELOG.md"
    if not target.is_file() or target.read_text(encoding="utf-8") != expected:
        raise ValueError("Root CHANGELOG.md is stale; run python tools/changelog.py --write")


def main():
    sys.stdout.reconfigure(encoding="utf-8")
    parser = argparse.ArgumentParser(description=__doc__)
    action = parser.add_mutually_exclusive_group(required=True)
    action.add_argument("--check", action="store_true", help="Reject a stale root changelog or mismatched manifest version")
    action.add_argument("--write", action="store_true", help="Regenerate only the root Markdown changelog")
    action.add_argument("--release", metavar="VERSION", help="Print generated Markdown notes for one GitHub release")
    args = parser.parse_args()
    try:
        if args.check:
            check()
            print("Changelog OK: root Markdown matches the packaged release history and manifest")
        else:
            releases = load()
            if args.write:
                with (ROOT / "CHANGELOG.md").open("w", encoding="utf-8", newline="\n") as stream:
                    stream.write(render(releases))
                print("Updated CHANGELOG.md from " + SOURCE.as_posix())
            else:
                release = next((r for r in releases if r["version"] == args.release), None)
                if release is None:
                    raise ValueError(f"No changelog entry for {args.release}")
                print(render_release(release), end="")
    except (ValueError, OSError) as error:
        parser.exit(1, f"Changelog check failed: {error}\n")


if __name__ == "__main__":
    main()
